script:
// Independently implemented from official WEBTOON public HTML; no upstream code copied.
// Protocol reference: Keiyoushi extensions-source all/webtoons (Apache-2.0),
// https://github.com/keiyoushi/extensions-source/tree/main/src/all/webtoons
// Public web episodes only: no age-gate cookies, login, paid/app-only API, or quality URL rewriting.
var ORIGIN = 'https://www.webtoons.com';
function param(url, key) {
  var m = String(url).match(new RegExp('[?&]' + key + '=([^&#]*)'));
  return m ? decodeURIComponent(m[1]) : '';
}
function official(url) {
  if (!/^https:\/\/www\.webtoons\.com\/zh-hant\//.test(url))
    throw new Error('WEBTOON：僅支援繁體中文官方公開網頁');
  return url;
}
function listUrl(url) {
  official(url);
  var id = param(url, 'title_no');
  if (!/^\d+$/.test(id) || !/\/list\?/.test(url))
    throw new Error('WEBTOON：作品網址缺少 title_no');
  return url.split('?')[0] + '?title_no=' + id;
}
async function html(url, referer) {
  official(url);
  var r = await triomi.fetch(url, {headers: {Referer: referer || ORIGIN + '/zh-hant/'}});
  if (r.status !== 200) throw new Error('WEBTOON：HTTP ' + r.status);
  if (r.url && /\/(?:login|ageVerification|age-gate)(?:[/?]|$)/i.test(r.url))
    throw new Error('WEBTOON：此內容需要登入或年齡驗證，請使用官方服務');
  if (/服务器停止响应|伺服器停止回應|无法显示此网页|無法顯示此網頁|Access Denied|Just a moment\.\.\./i.test(r.body))
    throw new Error('WEBTOON：官方伺服器暫時無法回應或限制存取');
  return r.body;
}
async function cards(body, url, searchMode) {
  var rows = await triomi.select(body, '.webtoon_list li a', {
    url: {selector: '.', attr: 'href', absolute: true},
    title: {selector: '.title'},
    coverUrl: {selector: 'img', attr: 'src', absolute: true},
    author: {selector: '.author'}
  }, url);
  var seen = {}, out = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i], id = param(row.url, 'title_no');
    if (!/^\d+$/.test(id) || !row.title || !/^https:\/\/www\.webtoons\.com\/zh-hant\//.test(row.url))
      throw new Error('WEBTOON：作品列表格式已變更');
    if (!seen[id]) {
      seen[id] = true;
      out.push({remoteId: id, title: row.title, url: listUrl(row.url), coverUrl: row.coverUrl, author: row.author});
    }
  }
  if (!out.length && !(searchMode && /webtoonCount:\s*0\b|class=["'][^"']*(?:no_result|search_no_result)[^"']*["']/i.test(body)))
    throw new Error('WEBTOON：找不到公開作品列表，可能需要驗證或網站已改版');
  return out;
}
async function discover(url, page) {
  if ((page || 1) > 1) return [];
  return cards(await html(url), url, false);
}
async function search(keyword, page) {
  page = page || 1;
  var url = ORIGIN + '/zh-hant/search/originals?keyword=' + encodeURIComponent(keyword) + '&page=' + page;
  return cards(await html(url), url, true);
}
async function detail(url, item) {
  url = listUrl(url);
  var titleId = param(url, 'title_no'), body = await html(url);
  var info = await triomi.select(body, 'html', {
    title: {selector: 'h1.subj, h3.subj'},
    author: {selector: 'meta[property="com-linewebtoon:webtoon:author"]', attr: 'content'},
    description: {selector: '#_asideDetail p.summary'},
    coverUrl: {selector: 'meta[property="og:image"]', attr: 'content', absolute: true},
    notice: {selector: '.detail_install_app'}
  }, url);
  if (!info.length || !info[0].title)
    throw new Error('WEBTOON：作品需要登入、年齡驗證，或詳情格式已變更');
  var data = info[0], result = Object.assign({}, item || {}, {
    remoteId: titleId, url: url, title: data.title,
    author: data.author || (item && item.author) || '',
    description: (data.description || '') + (data.notice ? '\n\n[官方網頁限制] ' + data.notice : ''),
    coverUrl: (item && item.coverUrl) || data.coverUrl || ''
  });
  var seen = {}, cursors = {}, chapters = [], cursor = 0;
  for (var page = 0; page < 100; page++) {
    var api = 'https://m.webtoons.com/api/v1/webtoon/' + titleId + '/episodes?pageSize=99999' + (cursor ? '&cursor=' + cursor : '');
    var response = await triomi.fetch(api, {headers: {Referer: 'https://m.webtoons.com/'}});
    if (response.status !== 200) throw new Error('WEBTOON：目錄 HTTP ' + response.status);
    if (response.url && response.url !== api) throw new Error('WEBTOON：目錄 API 重新導向');
    var payload;
    try { payload = JSON.parse(response.body); }
    catch (e) { throw new Error('WEBTOON：目錄 API JSON 格式已變更'); }
    var resultPage = payload && payload.result;
    if (!payload || payload.success !== true || !resultPage || !Array.isArray(resultPage.episodeList) || !resultPage.episodeList.length)
      throw new Error('WEBTOON：沒有完整公開目錄或 API 回應失敗');
    var next = resultPage.nextCursor;
    if (typeof next !== 'number' || !isFinite(next) || Math.floor(next) !== next || next < 0 || next > 9007199254740991 || (next && (next <= cursor || cursors[next])))
      throw new Error('WEBTOON：目錄游標無效，無法取得完整公開目錄');
    for (var i = 0; i < resultPage.episodeList.length; i++) {
      var row = resultPage.episodeList[i];
      if (!row || typeof row.episodeNo !== 'number' || !isFinite(row.episodeNo) || Math.floor(row.episodeNo) !== row.episodeNo || row.episodeNo <= 0 || row.episodeNo > 9007199254740991 || typeof row.episodeTitle !== 'string' || !row.episodeTitle.trim() || typeof row.viewerLink !== 'string')
        throw new Error('WEBTOON：章節資料格式已變更');
      var episode = String(row.episodeNo), viewer = row.viewerLink;
      if (/^\/zh-hant\//.test(viewer)) viewer = ORIGIN + viewer;
      official(viewer);
      if (!/^https:\/\/www\.webtoons\.com\/zh-hant\/[^?#]+\/viewer\?[^#]+$/.test(viewer) || param(viewer, 'title_no') !== titleId || param(viewer, 'episode_no') !== episode || (viewer.match(/[?&]title_no=/g) || []).length !== 1 || (viewer.match(/[?&]episode_no=/g) || []).length !== 1)
        throw new Error('WEBTOON：章節網址不屬於此作品');
      if (seen[episode]) throw new Error('WEBTOON：官方重複回傳章節，無法取得完整公開目錄');
      seen[episode] = true;
      chapters.push({remoteId: titleId + ':' + episode, title: row.episodeTitle, url: viewer, number: row.episodeNo});
    }
    if (!next) break;
    cursors[next] = true;
    cursor = next;
    if (page === 99) throw new Error('WEBTOON：目錄超過分頁上限，無法取得完整公開目錄');
  }
  chapters.sort(function (a, b) { return a.number - b.number; });
  return {item: result, chapters: chapters};
}
async function content(url, chapter) {
  official(url);
  var titleId = param(url, 'title_no'), episode = param(url, 'episode_no');
  if (!/^\d+$/.test(titleId) || !/^\d+$/.test(episode))
    throw new Error('WEBTOON：章節網址缺少穩定編號');
  var body = await html(url);
  var canonical = await triomi.select(body, 'meta[property="og:url"]', {url: {selector: '.', attr: 'content'}}, url);
  if (canonical.length && canonical[0].url && (param(canonical[0].url, 'title_no') !== titleId || param(canonical[0].url, 'episode_no') !== episode))
    throw new Error('WEBTOON：官方已重新導向其他章節；此話可能受限');
  var rows = await triomi.select(body, '#_imageList > img', {
    image: {selector: '.', attr: 'data-url', absolute: true},
    src: {selector: '.', attr: 'src', absolute: true}
  }, url);
  if (!rows.length)
    throw new Error('WEBTOON：此話未提供公開圖片，可能僅限 APP、付費、登入或年齡驗證；動態漫畫請至官方閱讀');
  var images = [];
  for (var i = 0; i < rows.length; i++) {
    var image = rows[i].image || rows[i].src;
    if (!/^https:\/\/[^/]+\//.test(image || '') || /(?:blank|transparent|loading)\.(?:gif|png)(?:[?]|$)/i.test(image))
      throw new Error('WEBTOON：正文圖片格式已變更，未取得可閱讀的公開圖片');
    images.push(image);
  }
  return {images: images, headers: {Referer: url}};
}
